export function SuccessState({
  label = "{{label}}",
  value = "{{value}}",
  message = "{{message}}",
  accent = "{{accent}}",
  showSuccess = {{showSuccess}},
}) {
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", maxWidth: 280 }}>
      <label htmlFor="ss-react-1" style={{ display: "block", marginBottom: 6, fontWeight: 500 }}>{label}</label>
      <input id="ss-react-1" type="text" defaultValue={value} aria-invalid="false" aria-describedby={showSuccess ? "ss-react-msg-1" : undefined} style={{
        width: "100%", boxSizing: "border-box", padding: "10px 12px", font: "inherit", color: "#241430",
        background: showSuccess ? `color-mix(in srgb, ${accent} 10%, #FAF7F2)` : "#FAF7F2",
        border: `1.5px solid ${showSuccess ? accent : "#24143040"}`, borderRadius: 8,
      }} />
      {showSuccess && <p id="ss-react-msg-1" style={{ margin: "6px 0 0", fontSize: 12, color: "#241430", fontWeight: 600 }}>✓ {message}</p>}
    </div>
  );
}
